  var hit = stat.rect(LINE_X1 - LINE_X0, 20).move(LINE_X0, y - 10).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(name + ' — ' + tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(name + ' level',
        'This blue line marks the relative enthalpy of the ' + name.toLowerCase() + ' phase. ' +
        tip + ' No absolute numbers are shown — only the vertical gaps between levels matter, ' +
        'and those gaps are the enthalpy changes of the phase transitions.');
    });
  return ln;
}
phaseLine(GAS_Y, 'Gas', true, 'the highest-energy state, with particles fully separated.');
phaseLine(LIQ_Y, 'Liquid', true, 'particles are still in contact but free to move past one another.');
phaseLine(SOL_Y, 'Solid', false, 'the lowest-energy state, with particles locked in place.');

/* ── state ────────────────────────────────────────────────── */
var state = { pathView: 'compare', phasePath: 'solid' };

function arrow(g, x, yBot, yTip, color, wdt, glow) {
  var hh = 17, hw = 8.5;
  if (glow) g.line(x, yBot, x, yTip + hh * 0.5).stroke({ color: color, width: wdt + 8, opacity: 0.16, linecap: 'butt' });
  g.line(x, yBot, x, yTip + hh - 1).stroke({ color: color, width: wdt, linecap: 'butt' });
  g.polygon([[x - hw, yTip + hh], [x + hw, yTip + hh], [x, yTip]]).fill(color);
}

function hotspot(g, x, yTop, yBot, tipTxt, title, body) {
  var r = g.rect(34, yBot - yTop).move(x - 17, yTop).fill('#fff').opacity(0);
  r.css('cursor', 'pointer');
  r.on('mousemove', function (e) { showTooltip(tipTxt, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(title, body); });
}

function render() {
  dyn.clear();
  var view = state.pathView, ph = state.phasePath;
  var subOn = (view !== 'twostep');
  var twoOn = (view !== 'direct');

  var subHot = subOn && view === 'direct';
  var fusHot = twoOn && (ph === 'melted' || ph === 'vaporized');
  var vapHot = twoOn && ph === 'vaporized';

  var subCol = subOn ? (subHot ? HOT : RED) : GRAY;
  var fusCol = twoOn ? (fusHot ? HOT : RED) : GRAY;
  var vapCol = twoOn ? (vapHot ? HOT : RED) : GRAY;
  var subTxtC = subOn ? '#000' : GRAYTXT;
  var twoTxtC = twoOn ? '#000' : GRAYTXT;

  // dashed guide at gas level (both routes finished)
  if (twoOn && ph === 'vaporized') {
    dyn.line(SUB_X, 82, BAR_X + BAR_W / 2, 82)
      .stroke({ color: '#9a9a9a', width: 1.6, dasharray: '7,5' });
  }

  // arrows
  arrow(dyn, SUB_X, SOL_Y, 82, subCol, 7, subHot);
  arrow(dyn, TWO_X, SOL_Y, 302, fusCol, 7, fusHot);
  arrow(dyn, TWO_X, 296, 82, vapCol, 7, vapHot);

  // running-total bar
  if (ph !== 'solid') {
    var top = (ph === 'melted') ? LIQ_Y : GAS_Y;
    dyn.rect(BAR_W, SOL_Y - top).move(BAR_X, top).fill(HOT).opacity(0.85);
    dyn.line(BAR_X - 8, top, BAR_X + BAR_W + 8, top).stroke({ color: HOT, width: 3 });
    dyn.line(BAR_X - 8, SOL_Y, BAR_X + BAR_W + 8, SOL_Y).stroke({ color: '#888', width: 2 });
  }

  // labels
  txt(dyn, 'Sublimation', 200, 343, { size: 21, anchor: 'middle', color: subTxtC, halo: true });
  deltaLabel(dyn, 200, 379, 'sub', 21, subTxtC);
  txt(dyn, 'Fusion', 434, 343, { size: 21, anchor: 'middle', color: twoTxtC, halo: true });
  deltaLabel(dyn, 434, 379, 'fus', 21, twoTxtC);
  txt(dyn, 'Vaporization', 460, 188, { size: 21, anchor: 'middle', color: twoTxtC, halo: true });
  deltaLabel(dyn, 460, 228, 'vap', 21, twoTxtC);

  // summation annotation
  if (ph === 'vaporized' && twoOn) {
    var sg = dyn.group(), cx = 0;
    function dl(sub, col) {
      var m = txt(sg, '\u0394H', cx, 0, { size: 20, color: col, italic: true });
      cx += m.bbox().width + 1.5;
      var s = txt(sg, sub, cx, 6.5, { size: 13, color: col });
      cx += s.bbox().width + 3;
    }
    function op(s) { var t = txt(sg, s, cx + 4, 0, { size: 20 }); cx += t.bbox().width + 11; }
    dl('sub', RED); op('='); dl('fus', HOT); op('+'); dl('vap', HOT);
    var b = sg.bbox();
    sg.rect(b.width + 16, b.height + 12).move(b.x - 8, b.y - 6)
      .fill('#fff').opacity(0.92).stroke({ color: '#e4c8c8', width: 1 }).radius(5).back();
    sg.translate(78, 140);
    sg.opacity(0);
    sg.animate(280).opacity(1);
  }

  // hotspots
  hotspot(dyn, SUB_X, 70, SOL_Y, 'Sublimation: solid \u2192 gas directly (\u0394H_sub)',
    'Sublimation',
    'This single long arrow takes the solid straight to the gas phase without ever being a liquid. ' +
    'Its length is \u0394H_sub, the enthalpy of sublimation. Notice it ends at exactly the same height ' +
    'as the two shorter arrows stacked together.');
  hotspot(dyn, TWO_X, 296, SOL_Y, 'Fusion: solid \u2192 liquid (\u0394H_fus)',
    'Fusion (melting)',
    'The short arrow lifts the sample from the Solid line to the Liquid line. ' +
    'The energy absorbed is \u0394H_fus, the enthalpy of fusion. It is much smaller than \u0394H_vap ' +
    'because melting only loosens the particles instead of separating them.');
  hotspot(dyn, TWO_X, 70, 296, 'Vaporization: liquid \u2192 gas (\u0394H_vap)',
    'Vaporization (boiling)',
    'This arrow carries the liquid the rest of the way up to the Gas line, absorbing \u0394H_vap. ' +
    'Separating particles completely costs much more energy than merely melting the solid, ' +
    'which is why this arrow is roughly twice as long as the fusion arrow.');

  if (ph !== 'solid') {
    var bt = (ph === 'melted') ? LIQ_Y : GAS_Y;
    var hb = dyn.rect(30, SOL_Y - bt + 10).move(BAR_X - 11, bt - 5).fill('#fff').opacity(0);
    hb.css('cursor', 'pointer');
    hb.on('mousemove', function (e) {
      showTooltip('Running total of energy absorbed so far: ' +
        (ph === 'melted' ? '\u0394H_fus' : '\u0394H_fus + \u0394H_vap'), e);
    }).on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Running energy total',
          'This bar accumulates the energy added along the two-step route. ' +
          'After melting it reaches the Liquid level; after boiling it reaches the Gas level — ' +
          'exactly the top of the single sublimation arrow.');
      });
  }

  var rv = document.getElementById('runVal');
  if (rv) rv.textContent = (state.phasePath === 'solid') ? ''
    : (state.phasePath === 'melted' ? 'total = \u0394H_fus' : 'total = \u0394H_fus + \u0394H_vap = \u0394H_sub');
  var pl = document.getElementById('phaseLabel');
  if (pl) pl.textContent = state.phasePath;
}

/* ── interactions ─────────────────────────────────────────── */
function toggle_pathView(v) { state.pathView = v; render(); }

function trigger_phasePath() {
  var order = ['solid', 'melted', 'vaporized'];
  var i = order.indexOf(state.phasePath);
  state.phasePath = order[(i + 1) % order.length];
  if (state.phasePath !== 'solid' && state.pathView === 'direct') {
    state.pathView = 'twostep';
    document.getElementById('pathViewInput').value = 'twostep';
  }
  render();
}

/* ── demo steps ───────────────────────────────────────────── */
var STEPS = [
  {
    t: 'Three energy levels',
    n: 'Three blue lines mark the relative enthalpy of solid, liquid and gas for the same substance. Higher line means higher energy; the liquid-to-gas gap is much larger than the solid-to-liquid gap.',
    s: { pathView: 'compare', phasePath: 'solid' }
  },
  {
    t: 'The direct route: sublimation',
    n: 'One long red arrow takes the solid straight to the gas. Its length is \u0394H_sub, the energy that must be absorbed for sublimation.',
    s: { pathView: 'direct', phasePath: 'solid' }
  },
  {
    t: 'Step 1 — melting',
    n: 'Switch to the two-step route and add \u0394H_fus: the sample climbs only from the Solid line to the Liquid line, and the running total on the right rises by that short amount.',
    s: { pathView: 'twostep', phasePath: 'melted' }
  },
  {
    t: 'Step 2 — vaporizing',
    n: 'Adding \u0394H_vap lifts the liquid the rest of the way to the Gas line. The running total now sits exactly at the top of the sublimation arrow.',
    s: { pathView: 'twostep', phasePath: 'vaporized' }
  },
  {
    t: 'Both routes, same height',
    n: 'Show the long arrow beside the two stacked arrows: they end at the same level, so \u0394H_sub = \u0394H_fus + \u0394H_vap. Enthalpy is a state function — the path does not matter.',
    s: { pathView: 'compare', phasePath: 'vaporized' }
  }
];
var stepI = 0;

function applyStep(i) {
  stepI = Math.max(0, Math.min(STEPS.length - 1, i));
  var st = STEPS[stepI];
  state.pathView = st.s.pathView;
  state.phasePath = st.s.phasePath;
  document.getElementById('pathViewInput').value = state.pathView;
  document.getElementById('stepTitle').textContent = (stepI + 1) + '. ' + st.t;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = (stepI + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(stepI + 1); }
function prevStep() { applyStep(stepI - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

