var _cont = document.getElementById('container');
var draw = SVG().addTo(_cont).size('100%', '100%');
var W = 700, H = 490;
draw.viewbox(0, 0, W, H);

/* ── geometry ─────────────────────────────────────────────── */
var GAS_Y = 75, LIQ_Y = 298, SOL_Y = 413;
var LINE_X0 = 60, LINE_X1 = 596;          // shortened so the bar never crowds labels
var SUB_X = 283, TWO_X = 369;
var TIP_Y = 82;                            // arrow tip height (just under the Gas line)
var BAR_X = 640, BAR_W = 9;

var BLUE = '#4169e1';
var RED = '#b22222';
var HOT = '#e21f16';
var GRAY = '#d2d2d2';
var GRAYTXT = '#bcbcbc';

var stat = draw.group();
var dyn = draw.group();

/* ── text helpers ─────────────────────────────────────────── */
function halo(t) {
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}
function txt(g, str, x, y, o) {
  o = o || {};
  var t = g.plain(str).font({
    family: 'sans-serif',
    size: o.size || 20,
    anchor: o.anchor || 'start'
  }).fill(o.color || '#000');
  t.attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  if (o.italic) t.font({ style: 'italic' });
  if (o.bold) t.font({ weight: 'bold' });
  if (o.halo) halo(t);
  return t;
}

/* Tight "ΔH" + subscript. Widths are measured BEFORE the white halo stroke is
   applied, otherwise getBBox() includes the 4-unit stroke and opens a gap. */
function dhText(g, x, y, sub, o) {
  o = o || {};
  var size = o.size || 21, col = o.color || '#000';
  var m = g.plain('\u0394H').font({ family: 'sans-serif', size: size, style: 'italic' })
    .fill(col).attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  var w = m.bbox().width;
  var s = g.plain(sub).font({ family: 'sans-serif', size: size * 0.62 })
    .fill(col).attr({ x: x + w + 0.5, y: y + size * 0.30, 'dominant-baseline': 'middle' });
  var total = w + 0.5 + s.bbox().width;
  if (o.center) {
    m.attr('x', x - total / 2);
    s.attr('x', x - total / 2 + w + 0.5);
  }
  if (o.halo !== false) { halo(m); halo(s); }
  return total;
}

/* ── static scene ─────────────────────────────────────────── */
stat.line(38, 478, 38, 18).stroke({ color: '#000', width: 3, linecap: 'butt' });
stat.polygon([[38, 8], [31.5, 22], [44.5, 22]]).fill('#000');
var enLab = txt(stat, 'Energy', 20, 250, { size: 21, bold: true, anchor: 'middle' });
enLab.rotate(-90, 20, 250);

function phaseLine(y, name, above, tip) {
  stat.line(LINE_X0, y, LINE_X1, y).stroke({ color: BLUE, width: 5.5, linecap: 'butt' });
  txt(stat, name, LINE_X1 - 2, above ? y - 20 : y + 21, { size: 21, anchor: 'end', halo: true });
  var hit = stat.rect(LINE_X1 - LINE_X0, 20).move(LINE_X0, y - 10).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip(name + ' — ' + tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(name + ' level',
        'This blue line marks the relative enthalpy of the ' + name.toLowerCase() + ' phase. ' +
        tip + ' No absolute numbers are shown — only the vertical gaps between levels matter, ' +
        'and those gaps are the enthalpy changes of the phase transitions.');
    });
}
phaseLine(GAS_Y, 'Gas', true, 'the highest-energy state, with particles fully separated.');
phaseLine(LIQ_Y, 'Liquid', true, 'particles are still in contact but free to move past one another.');
phaseLine(SOL_Y, 'Solid', false, 'the lowest-energy state, with particles locked in place.');

/* ── state ────────────────────────────────────────────────── */
var state = { pathView: 'compare', phasePath: 'solid' };

function arrow(g, x, yBot, yTip, color, wdt, glow) {
  var hh = 17, hw = 8.5;
  if (glow) g.line(x, yBot, x, yTip + hh * 0.5).stroke({ color: color, width: wdt + 8, opacity: 0.16, linecap: 'butt' });
  g.line(x, yBot, x, yTip + hh - 1).stroke({ color: color, width: wdt, linecap: 'butt' });
  g.polygon([[x - hw, yTip + hh], [x + hw, yTip + hh], [x, yTip]]).fill(color);
}

function hotspot(g, x, yTop, yBot, tipTxt, title, body) {
  var r = g.rect(34, yBot - yTop).move(x - 17, yTop).fill('#fff').opacity(0);
  r.css('cursor', 'pointer');
  r.on('mousemove', function (e) { showTooltip(tipTxt, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(title, body); });
}

function render() {
  dyn.clear();
  var view = state.pathView, ph = state.phasePath;
  var subOn = (view !== 'twostep');
  var twoOn = (view !== 'direct');

  var subHot = subOn && view === 'direct';
  var fusHot = twoOn && (ph === 'melted' || ph === 'vaporized');
  var vapHot = twoOn && ph === 'vaporized';

  var subCol = subOn ? (subHot ? HOT : RED) : GRAY;
  var fusCol = twoOn ? (fusHot ? HOT : RED) : GRAY;
  var vapCol = twoOn ? (vapHot ? HOT : RED) : GRAY;
  var subTxtC = subOn ? '#000' : GRAYTXT;
  var twoTxtC = twoOn ? '#000' : GRAYTXT;

  // faint dashed guide: tops of both routes sit at the same height
  if (twoOn && ph === 'vaporized') {
    dyn.line(SUB_X, TIP_Y, BAR_X + BAR_W / 2, TIP_Y)
      .stroke({ color: '#9a9a9a', width: 1.6, dasharray: '7,5' });
  }

  // arrows
  arrow(dyn, SUB_X, SOL_Y, TIP_Y, subCol, 7, subHot);
  arrow(dyn, TWO_X, SOL_Y, 302, fusCol, 7, fusHot);
  arrow(dyn, TWO_X, 296, TIP_Y, vapCol, 7, vapHot);

  // running-total bar (study aid), kept well clear of the phase-line labels
  if (ph !== 'solid') {
    var top = (ph === 'melted') ? LIQ_Y : GAS_Y;
    dyn.rect(BAR_W, SOL_Y - top).move(BAR_X, top).fill(HOT).opacity(0.85);
    dyn.line(BAR_X - 7, top, BAR_X + BAR_W + 7, top).stroke({ color: HOT, width: 3 });
    dyn.line(BAR_X - 7, SOL_Y, BAR_X + BAR_W + 7, SOL_Y).stroke({ color: '#888', width: 2 });
    var cap = txt(dyn, 'running total', BAR_X + 26, (top + SOL_Y) / 2,
      { size: 12, anchor: 'middle', color: '#8a8a8a', halo: true });
    cap.rotate(-90, BAR_X + 26, (top + SOL_Y) / 2);
  }

  // labels (drawn last, haloed, tucked beside their own arrows)
  txt(dyn, 'Sublimation', 190, 343, { size: 21, anchor: 'middle', color: subTxtC, halo: true });
  dhText(dyn, 190, 379, 'sub', { size: 21, color: subTxtC, center: true });

  txt(dyn, 'Fusion', 424, 343, { size: 21, anchor: 'middle', color: twoTxtC, halo: true });
  dhText(dyn, 424, 379, 'fus', { size: 21, color: twoTxtC, center: true });

  txt(dyn, 'Vaporization', 447, 188, { size: 21, anchor: 'middle', color: twoTxtC, halo: true });
  dhText(dyn, 447, 228, 'vap', { size: 21, color: twoTxtC, center: true });

  // summation annotation in the upper-left whitespace
  if (ph === 'vaporized' && twoOn) {
    var sg = dyn.group(), cx = 0, sz = 19;
    cx += dhText(sg, cx, 0, 'sub', { size: sz, color: RED, halo: false }) + 8;
    var eq = txt(sg, '=', cx, 0, { size: sz }); cx += eq.bbox().width + 8;
    cx += dhText(sg, cx, 0, 'fus', { size: sz, color: HOT, halo: false }) + 8;
    var pl = txt(sg, '+', cx, 0, { size: sz }); cx += pl.bbox().width + 8;
    cx += dhText(sg, cx, 0, 'vap', { size: sz, color: HOT, halo: false });
    var b = sg.bbox();
    sg.rect(b.width + 18, b.height + 12).move(b.x - 9, b.y - 6)
      .fill('#fff').opacity(0.94).stroke({ color: '#e4c8c8', width: 1 }).radius(5).back();
    sg.translate(66, 148);
    sg.opacity(0);
    sg.animate(280).opacity(1);
  }

  // hotspots
  hotspot(dyn, SUB_X, 70, SOL_Y, 'Sublimation: solid \u2192 gas directly (\u0394H\u2080sub)'.replace('\u2080', ''),
    'Sublimation',
    'This single long arrow takes the solid straight to the gas phase without ever being a liquid. ' +
    'Its length is \u0394H(sub), the enthalpy of sublimation. Notice it ends at exactly the same height ' +
    'as the two shorter arrows stacked together.');
  hotspot(dyn, TWO_X, 296, SOL_Y, 'Fusion: solid \u2192 liquid (\u0394H fus)',
    'Fusion (melting)',
    'The short arrow lifts the sample from the Solid line to the Liquid line. ' +
    'The energy absorbed is \u0394H(fus), the enthalpy of fusion. It is much smaller than \u0394H(vap) ' +
    'because melting only loosens the particles instead of separating them.');
  hotspot(dyn, TWO_X, 70, 296, 'Vaporization: liquid \u2192 gas (\u0394H vap)',
    'Vaporization (boiling)',
    'This arrow carries the liquid the rest of the way up to the Gas line, absorbing \u0394H(vap). ' +
    'Separating particles completely costs much more energy than merely melting the solid, ' +
    'which is why this arrow is roughly twice as long as the fusion arrow.');

  if (ph !== 'solid') {
    var bt = (ph === 'melted') ? LIQ_Y : GAS_Y;
    var hb = dyn.rect(44, SOL_Y - bt + 10).move(BAR_X - 12, bt - 5).fill('#fff').opacity(0);
    hb.css('cursor', 'pointer');
    hb.on('mousemove', function (e) {
      showTooltip('Running total of energy absorbed so far: ' +
        (ph === 'melted' ? '\u0394H(fus)' : '\u0394H(fus) + \u0394H(vap)'), e);
    }).on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Running energy total (study aid)',
          'This bar is not part of the textbook diagram — it accumulates the energy added along the ' +
          'two-step route. After melting it reaches the Liquid level; after boiling it reaches the ' +
          'Gas level, exactly the top of the single sublimation arrow.');
      });
  }

  var rv = document.getElementById('runVal');
  if (rv) rv.textContent = (state.phasePath === 'solid') ? 'total = 0'
    : (state.phasePath === 'melted' ? 'total = \u0394H(fus)'
      : 'total = \u0394H(fus) + \u0394H(vap) = \u0394H(sub)');
  var pl2 = document.getElementById('phaseLabel');
  if (pl2) pl2.textContent = state.phasePath;
}

/* ── interactions ─────────────────────────────────────────── */
function toggle_pathView(v) { state.pathView = v; render(); }

function trigger_phasePath() {
  var order = ['solid', 'melted', 'vaporized'];
  var i = order.indexOf(state.phasePath);
  state.phasePath = order[(i + 1) % order.length];
  if (state.phasePath !== 'solid' && state.pathView === 'direct') {
    state.pathView = 'twostep';
    document.getElementById('pathViewInput').value = 'twostep';
  }
  render();
}

/* ── demo steps ───────────────────────────────────────────── */
var STEPS = [
  {
    t: 'Three energy levels',
    n: 'Three blue lines mark the relative enthalpy of solid, liquid and gas for the same substance. Higher line means higher energy; the liquid-to-gas gap is much larger than the solid-to-liquid gap.',
    s: { pathView: 'compare', phasePath: 'solid' }
  },
  {
