    s: { pathView: 'compare', phasePath: 'vaporized' }
  }
];
var stepI = 0;

function applyStep(i) {
  stepI = Math.max(0, Math.min(STEPS.length - 1, i));
  var st = STEPS[stepI];
  state.pathView = st.s.pathView;
  state.phasePath = st.s.phasePath;
  document.getElementById('pathViewInput').value = state.pathView;
  document.getElementById('stepTitle').textContent = (stepI + 1) + '. ' + st.t;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = (stepI + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(stepI + 1); }
function prevStep() { applyStep(stepI - 1); }

